/* harmony default export */ __webpack_exports__["default"] = ({
  name: 'AppControls',
  components: {
    ActionButton: (_nextcloud_vue_dist_Components_ActionButton__WEBPACK_IMPORTED_MODULE_0___default()),
    Breadcrumbs: (_nextcloud_vue_dist_Components_Breadcrumbs__WEBPACK_IMPORTED_MODULE_1___default()),
    Breadcrumb: (_nextcloud_vue_dist_Components_Breadcrumb__WEBPACK_IMPORTED_MODULE_2___default())
  },

  data() {
    return {};
  },

  computed: {
    searchTitle() {
      if (this.$route.param.query === 'cat') {
        return this.$i18n.t('Category');
      } else if (this.$route.param.query === 'name') {
        return this.$i18n.t('Recipe name');
      } else if (this.$route.param.query === 'tag') {
        return this.$i18n.t('Tag');
      } else {
        return this.$i18n.t('Search for recipes');
      }
    }

  },
  methods: {
    deleteRecipe: function () {
      // Confirm delete
      if (!confirm(this.$t('Confirm delete'))) {
        return;
      }

      let id = this.$store.state.recipe.id;
      let $this = this;
      $.ajax({
        url: window.baseUrl + '/api/recipes/' + id,
        method: 'DELETE'
      }).done(function (reply) {
        window.goTo('/');
      }).fail(function (e) {
        alert($this.$t('Delete failed'));

        if (e && e instanceof Error) {
          throw e;
        }
      });
    },
    printRecipe: function () {
      window.print();
    }
  }
});

